import { useState } from "react";

function DanhSach() {
  const [items, setItems] = useState(["A", "B"]);
  const them = () => setItems([...items, "Moi"]);
  return (
    <div>
      <button onClick={them}>Them</button>
      <ul>
        {items.map((it, i) => (
          <li key={i}>{it}</li>
        ))}
      </ul>
    </div>
  );
}

export default DanhSach;
